# Universal Dependencies v2

__META_SOURCE_URL__=https://universaldependencies.org/u/dep/index.html
__META_TYPE_BASE__=de.tudarmstadt.ukp.dkpro.core.api.syntax.type.dependency.

# acl: clausal modifier of noun (adnominal clause)
acl=Dependency
# advcl: adverbial clause modifier
advcl=ADVCL
# advmod: adverbial modifier
advmod=ADVMOD
# amod: adjectival modifier
amod=AMOD
# appos: appositional modifier
appos=APPOS
# aux: auxiliary
aux=AUX0
# case: case marking
case=PREP
# cc: coordinating conjunction
cc=CC
# ccomp: clausal complement
ccomp=CCOMP
# clf: classifier
clf=Dependency
# compound: compound
compound=NN
# conj: conjunct
conj=CONJ
# cop: copula
cop=COP
# csubj: clausal subject
csubj=CSUBJ
# dep: unspecified dependency
dep=DEP
# det: determiner
det=DET
# discourse: discourse element
discourse=Dependency
# dislocated: dislocated elements
dislocated=Dependency
# expl: expletive
expl=EXPL
# fixed: fixed multiword expression
fixed=MWE
# flat: flat multiword expression
flat=Dependency
# goeswith: goes with
goeswith=Dependency
# iobj: indirect object
iobj=IOBJ
# list: list
list=Dependency
# mark: marker
mark=MARK
# nmod: nominal modifier
nmod=Dependency
# nsubj: nominal subject
nsubj=NSUBJ
# nummod: numeric modifier
nummod=Dependency
# obj: object
obj=DOBJ
# obl: oblique nominal
obl=Dependency
# orphan: orphan
orphan=Dependency
# parataxis: parataxis
parataxis=PARATAXIS
# punct: punctuation
punct=PUNCT
# reparandum: overridden disfluency
reparandum=Dependency
# root: root
root=ROOT
# vocative: vocative
vocative=Dependency
# xcomp: open clausal complement
xcomp=XCOMP

# Subtypes used by the French UD treebanks.
# Subtypes not listed here are mapped like their base relation (e.g. obl:arg like obl).
# acl:relcl: relative clause modifier
acl\:relcl=RCMOD
# aux:pass: passive auxiliary
aux\:pass=AUXPASS
# csubj:pass: clausal passive subject
csubj\:pass=CSUBJPASS
# nsubj:pass: passive nominal subject
nsubj\:pass=NSUBJPASS
# obl:agent: agent in passive
obl\:agent=AGENT

# Catch-all mapping
*=Dependency
